window.__finlexDocLoaded(10191,{"id":10191,"articles":[{"id":1000795,"no":"Overview","heading":"Scope & Core Objective (Public Summary)","text":"Governs presentation of net income, Other Comprehensive Income (OCI), Accumulated OCI (AOCI), and footnote disaggregation of income statement expenses (ASC 220-40, added by ASU 2024-03).","seq":0},{"id":1000796,"no":"ASC 220-10 / 220-40","heading":"OCI Presentation & ASU 2024-03 Expense Disaggregation (DISE)","text":"• Single or Two-Statement Approach (ASC 220-10-45): Present comprehensive income in one continuous statement or two consecutive statements.\n• Recycling: Virtually all US GAAP OCI items (AFS debt unrealized gains/losses, cash flow hedges, pension adjustments, CTA) recycle to net income (unlike IFRS equity FVOCI).\n• Disaggregation of Income Statement Expenses — DISE (ASC 220-40, ASU 2024-03, effective fiscal years beginning after Dec 15, 2026): Public business entities must disclose tabular breakdowns in footnotes for purchases of inventory, employee compensation, depreciation, intangible amortization, and DD&A embedded in each income statement expense line.","seq":1},{"id":1000797,"no":"US GAAP vs. IFRS / CAS","heading":"Key Cross-Framework Differences","text":"• Structure vs. IFRS 18: IFRS 18 mandates three standardized face-of-P&L categories (Operating, Investing, Financing) plus MPM disclosures; US GAAP (ASU 2024-03) leaves the face of the income statement flexible (SEC Reg S-X drives public company lines) and requires granular expense disaggregation in the footnotes.","seq":2},{"id":1000798,"no":"Official Access","heading":"Official FASB Codification & Reference Entry","text":"Official Portal (FASB Accounting Standards Codification®): https://asc.fasb.org/\nStatus: in_force (FASB ASC free Basic View available at https://asc.fasb.org/).","seq":3}]});
